import {letters,selectQuestions,remaining,score,breakdown,display,choosePractice,rememberQuestions,layerOf,ORIGINAL_LABEL,NEW_LABEL} from './core.js';
const app=document.querySelector('#app'),PREFIX='signal432.v1.';
let storageFailed=false;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(PREFIX+key))??fallback;}catch{return fallback;}};
const write=(key,value)=>{try{localStorage.setItem(PREFIX+key,JSON.stringify(value));}catch{storageFailed=true;}};
const esc=s=>display(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=s=>esc(s).replace(/\n/g,'<br>');
let bank=[],eligible=[],subjects=[],session=read('session',null),history=read('history',[]),seen=read('seen',[]),view='home',mode='full',subject='',topic='',difficulty='',count=20,bankPage=0,result=null,reviewResult=false,dialog=false,activeBackup=null;
let newBank=[],allBank=[],newSeen=read('seen.new',[]),pool='original',bankLayer='original',originalPercent=50;
const isFull=()=>['full','new','mixed','auto'].includes(mode);
const poolLabel=q=>layerOf(q)==='new'?NEW_LABEL:ORIGINAL_LABEL;
const scopedBank=()=>bankLayer==='new'?newBank:bankLayer==='mixed'?allBank:bank;
const available=()=>pool==='new'?newBank:pool==='original'?eligible:[...eligible,...newBank];
const topicsFor=source=>[...new Set(source.filter(q=>!subject||q.subject===subject).flatMap(q=>q.related_topics||[q.topic]))].sort();
let theme=read('theme','light');document.documentElement.dataset.theme=theme;
function button(label,action,cls='',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function save(){if(!reviewResult)write('session',session);}
const sessionQuestions=()=>session?session.ids.map(id=>allBank.find(q=>q.id===id)).filter(Boolean):[];
function header(){return `<header class="topbar"><div class="brand"><span class="brand-icon">S</span><div>Signal<span class="brand-light">Practice</span><small>RRB TECHNICIAN · GRADE-I SIGNAL</small></div></div><nav aria-label="Main navigation">${button('Practice','home',view==='home'||view==='setup'?'nav active':'nav')}${button('Question bank','bank',view==='bank'?'nav active':'nav')}${button('Results','history',view==='history'?'nav active':'nav')}${button(theme==='dark'?'Light theme':'Dark theme','theme','theme')}</nav></header>`;}
function render(){app.innerHTML=header()+`<main>${storageFailed?'<div class="notice">Browser storage is unavailable. Keep this page open to retain this session.</div>':''}${view==='home'?home():view==='setup'?setup():view==='practice'?practice():view==='bank'?browse():view==='result'?results():historyView()}</main><footer>RRB Technician Grade-I Signal · Independent practice resource <span>Original & supplementary questions · No official PYQ claim</span></footer>`+(dialog?confirmDialog():'');updateTimer();}
function home(){return `<div class="page-title"><div><div class="eyebrow">YOUR PRACTICE DESK</div><h1>A little practice. A stronger preparation.</h1><p>Choose your session. Get feedback with every answer.</p></div><div class="bank-total"><strong>432</strong><span>questions in your bank</span></div></div>${session&&!session.submitted?`<div class="resume"><div><strong>Your practice is saved</strong><span>${esc(session.name)} · ${Object.keys(session.answers).length} of ${session.ids.length} answered · timer continues while away</span></div>${button('Resume practice','resume','primary')}</div>`:''}<div class="modes"><section class="full-card"><div class="eyebrow">THE ORIGINAL BANK</div><h2>Original Bank CBT</h2><p>Settle into the exam rhythm.<br>Practice across all five subjects.</p><div class="full-stats"><div><b>100</b><span>questions</span></div><div><b>90</b><span>minutes</span></div><div><b>100</b><span>marks</span></div></div>${button('Full Mock — Original Bank','mode','light-primary','data-mode="full"')}<small>+1 correct &nbsp; · &nbsp; −⅓ wrong &nbsp; · &nbsp; Instant feedback</small></section><div class="other-modes"><section class="mode-card"><span class="mode-number">01</span><div><h2>Subject Practice</h2><p>Give one subject your full attention.</p></div>${button('Choose subject','mode','secondary','data-mode="subject"')}</section><section class="mode-card"><span class="mode-number">02</span><div><h2>Topic Practice</h2><p>Work on the concepts that need another look.</p></div>${button('Choose topic','mode','secondary','data-mode="topic"')}</section><section class="mode-card"><span class="mode-number">03</span><div><h2>Quick Practice</h2><p>10 or 20 questions. Make a small break count.</p></div>${button('Quick Practice','mode','secondary','data-mode="quick"')}</section></div></div>${layer2Home()}<section class="subject-strip"><div class="section-heading"><h2>Your question bank</h2>${button('Browse all questions','bank','text-button')}</div><div class="subject-counts">${subjects.map(s=>`<div><b>${bank.filter(q=>q.subject===s).length}</b><span>${esc(s)}</span></div>`).join('')}</div><p class="small muted">431 questions available for scored practice. One supplied question has an answer-key conflict and is kept in the bank for review.</p></section>${history.length?`<section class="recent"><div><h2>Last practice</h2><p>${esc(history[0].name)} · ${new Date(history[0].ended).toLocaleDateString()}</p></div><strong>${history[0].stats.marks.toFixed(2)} <small>/ ${history[0].stats.total}</small></strong>${button('View result','recent','secondary','data-index="0"')}</section>`:''}`;}
function layer2Home(){const used=eligible.filter(q=>seen.includes(q.id)).length;return `<section class="layer-section"><div class="section-heading"><div><div class="eyebrow">A SECOND PRACTICE LAYER</div><h2>Go beyond your original bank</h2></div><span class="layer-label new">${newBank.length} new questions</span></div><p class="muted">NEW — BANK-BASED PRACTICE. Paired application cases with worked explanations; not official PYQs.</p><div class="layer-cards"><section class="panel"><h2>New Bank-Based CBT</h2><p>100 new questions · 90 minutes<br>Two independent cases in each question.</p>${button('Start New CBT','mode','primary','data-mode="new" '+(newBank.length>=100?'':'disabled'))}</section><section class="panel"><h2>Mixed CBT</h2><p>Choose your Original + New split.<br>The pool is labelled on every question.</p>${button('Configure Mixed CBT','mode','secondary','data-mode="mixed" '+(newBank.length>=100?'':'disabled'))}</section><section class="panel"><h2>Continue with unseen questions</h2><p>${used} / 431 original questions seen. Fill a 100-question test with unseen originals, then new questions.</p>${button('Continue practice','mode','secondary','data-mode="auto" '+(newBank.length>=100?'':'disabled'))}</section></div><p class="small muted">This is a finite bank of 1,000 distinct paired-case combinations. Individual cases recur in different combinations. After a pool is exhausted, its least recently used questions return.</p>${newBank.length?'':'<p class="notice">The new bank could not load. Original Bank CBT remains available; reload to retry Layer 2.</p>'}</section>`;}
function poolControls(){return `<label>Question pool<select data-field="pool"><option value="original" ${pool==='original'?'selected':''}>Original bank</option><option value="new" ${pool==='new'?'selected':''}>New — Bank-Based Practice</option><option value="mixed" ${pool==='mixed'?'selected':''}>Original + New</option></select></label>${pool==='mixed'?ratioControl():''}`;}
function ratioControl(){return `<label>Original / New split<select data-field="ratio">${[0,25,50,75,100].map(n=>`<option value="${n}" ${originalPercent===n?'selected':''}>${n}% original / ${100-n}% new</option>`).join('')}</select></label>`;}
function select(label,key,values,value,allLabel){return `<label>${label}<select data-field="${key}">${allLabel?`<option value="">${allLabel}</option>`:''}${values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function filtered(source=available()){return source.filter(q=>(!subject||q.subject===subject)&&(!topic||q.topic===topic||q.related_topics?.includes(topic))&&(!difficulty||q.difficulty===difficulty));}
function setup(){const title={full:'Full Mock — Original Bank',new:'Full Mock — New Practice',mixed:'Mixed Full Mock',auto:'Continue Practice',subject:'Subject Practice',topic:'Topic Practice',quick:'Quick Practice'}[mode];const candidates=isFull()||mode==='quick'?available():filtered();const n=isFull()?Math.min(100,candidates.length):Math.min(count,candidates.length);return `<div class="page-title"><div><div class="eyebrow">PRACTICE / SESSION SETUP</div><h1>${title}</h1><p>Answers and explanations appear as soon as you choose an option.</p></div>${button('Back to practice','home','secondary')}</div><div class="setup-grid"><section class="panel setup-panel"><h2>Make this session yours</h2>${mode==='mixed'?ratioControl():!isFull()?poolControls():''}${mode==='auto'?'<p class="notice">Unseen original questions are used first. Any remaining places use the new practice bank.</p>':''}${mode==='subject'||mode==='topic'?`<div class="form-row">${select('Subject','subject',subjects,subject)}${mode==='topic'?select('Topic','topic',topicsFor(available()),topic):''}</div>`:''}${!isFull()?`<label>Number of questions<select data-field="count">${[10,20,50].filter(n=>mode!=='quick'||n<=20).map(n=>`<option ${count===n?'selected':''}>${n}</option>`).join('')}</select></label>`:''}<div class="session-spec"><div><b>${n}</b><span>questions</span></div><div><b>${isFull()?90:Math.max(1,Math.ceil(n*.9))}</b><span>minutes</span></div><div><b>${n}</b><span>maximum marks</span></div></div><p class="muted">${candidates.length} eligible questions. Previously unseen questions are chosen first; no question repeats within a session.</p>${session&&!session.submitted?'<p class="notice">Starting this session replaces your saved unfinished practice.</p>':''}${button('Start Test','start','primary large',n?'':'disabled')}</section><aside class="instructions"><div class="eyebrow">BEFORE YOU BEGIN</div><h2>Practice with feedback</h2><ol><li>Select A, B, C or D to see the answer and explanation immediately.</li><li>Jump to any question using the palette. Mark questions to revisit.</li><li>Earn 1 mark for a correct answer. A wrong answer deducts ⅓ mark.</li><li>The timer keeps running if you leave. At zero, your test is submitted automatically.</li></ol><p>Your latest selected answers determine your practice score.</p><p class="small">Progress is saved in this browser. Clearing browser data removes local history.</p></aside></div>`;}
function start(){const candidates=isFull()||mode==='quick'?available():filtered();const qs=choosePractice({original:candidates.filter(q=>layerOf(q)==='original'),newBank:candidates.filter(q=>layerOf(q)==='new'),count:isFull()?100:count,pool,originalPercent,originalHistory:seen,newHistory:newSeen});if(!qs.length)return;seen=rememberQuestions(seen,qs.filter(q=>layerOf(q)==='original').map(q=>q.id));newSeen=rememberQuestions(newSeen,qs.filter(q=>layerOf(q)==='new').map(q=>q.id));write('seen',seen);write('seen.new',newSeen);session={id:crypto.randomUUID(),name:{full:'Full Mock Test',new:'Full Mock — New Practice',mixed:'Mixed Full Mock',auto:'Continue Practice',subject:subject+' Practice',topic:topic+' Practice',quick:'Quick Practice'}[mode],practicePool:pool,ids:qs.map(q=>q.id),answers:{},marked:{},index:0,started:Date.now(),deadline:Date.now()+(isFull()?90:Math.max(1,Math.ceil(qs.length*.9)))*60000,submitted:false};save();view='practice';reviewResult=false;render();window.scrollTo(0,0);}
function explanation(q,selected,browsing=false){let wrong=selected&&selected!==q.correct_option;const fields=[['Concept',q.concept],['Formula',q.formula],['Given',q.given],['Calculation',q.calculation],['Final Answer',q.final_answer],['Why this answer is correct',q.why_correct]];const structured=fields.some(([,v])=>v);return `<section class="feedback ${wrong?'wrong':'correct'}" aria-live="polite"><div class="feedback-heading"><strong>${browsing?'Answer & explanation':wrong?'✗ Wrong':'✓ Correct'}</strong><span>Correct Answer: <b>${q.correct_option}</b> · ${esc(q['option_'+q.correct_option.toLowerCase()])}</span></div><div class="explanation">${structured?fields.filter(([,v])=>v&&!/^(n\/?a|not applicable)[.!]?$/i.test(v.trim())).map(([k,v])=>`<div class="explain-part ${k==='Formula'?'formula':''}"><h3>${k}</h3><p>${text(v)}</p></div>`).join(''):`<div class="explain-part"><h3>Explanation</h3><p>${text(q.explanation)}</p></div>`}${wrong?`<div class="explain-part why-wrong"><h3>Why ${selected} is incorrect</h3><p>${text(q.why_wrong?.[selected]||`Your choice was ${selected}: ${q['option_'+selected.toLowerCase()]}. The supplied solution gives ${q.correct_option}: ${q['option_'+q.correct_option.toLowerCase()]}.`)}${!q.why_wrong?.[selected]?' Refer to the worked explanation above; this record has no separate explanation for this option.':''}</p></div>`:''}${structured&&q.explanation?`<details><summary>Full supplied explanation</summary><p>${text(q.explanation)}</p></details>`:''}</div></section>`;}
function practice(){const qs=sessionQuestions(),q=qs[session.index];if(!q)return '<p>No question found.</p>';const chosen=session.answers[q.id],s=score(qs,session.answers),marked=Object.values(session.marked).filter(Boolean).length;return `<div class="exam-head"><div><div class="eyebrow">RRB TECHNICIAN GRADE-I SIGNAL</div><h1>${esc(session.name)}</h1><p>${qs.length} Questions <span>•</span> ${qs.length} Marks <span>•</span> +1 / −⅓</p></div><div class="timer-box"><span>${reviewResult?'COMPLETED':'TIME REMAINING'}</span><b id="timer">--:--</b></div>${button(reviewResult?'Back to result':'Submit test',reviewResult?'back-result':'submit',reviewResult?'secondary':'danger-outline')}</div><div class="exam-grid"><section class="question-panel"><div class="question-meta"><span class="question-number">Question ${session.index+1} <small>/ ${qs.length}</small></span><span class="badge">${esc(q.difficulty)}</span><span class="marks">+1 &nbsp; −⅓</span></div><div class="subject-line"><span class="layer-label ${layerOf(q)}">${poolLabel(q)}</span><br>${esc(q.subject)} <span>/</span> ${esc(q.layer==='new'?q.subtopic:q.topic)}</div><h2 class="question-text" tabindex="-1">${text(q.question_text)}</h2><div class="options" role="group" aria-label="Answer options">${letters.map(l=>`<button class="option ${chosen===l?'selected':''} ${chosen||reviewResult?l===q.correct_option?'answer-correct':chosen===l?'answer-wrong':'':''}" data-action="answer" data-letter="${l}" aria-pressed="${chosen===l}" ${reviewResult?'disabled':''}><span class="option-letter">${l}</span><span>${text(q['option_'+l.toLowerCase()])}</span>${chosen===l?'<span class="chosen-label">Selected</span>':''}</button>`).join('')}</div>${chosen||reviewResult?explanation(q,chosen,!chosen):'<p class="answer-hint">Choose an option to see the answer and explanation.</p>'}<div class="question-actions">${button('Previous','previous','secondary',session.index===0?'disabled':'')}${!reviewResult?button('Clear Answer','clear','text-button',chosen?'':'')+button(session.marked[q.id]?'Unmark Review':'Mark for Review','mark',session.marked[q.id]?'review-button marked':'review-button','aria-pressed="'+!!session.marked[q.id]+'"'):''}${button(session.index===qs.length-1?(reviewResult?'Back to result':'Finish test'):'Save/Next',session.index===qs.length-1?(reviewResult?'back-result':'submit'):'next','primary')}</div></section><aside class="palette-panel"><div class="palette-heading"><h2>Question palette</h2><span>${s.attempted}/${qs.length}</span></div><div class="progress-track"><div style="width:${s.attempted/qs.length*100}%"></div></div><div class="palette-counters"><span><i class="green"></i>Answered: <b>${s.attempted}</b></span><span><i class="yellow"></i>Marked for Review: <b>${marked}</b></span><span><i></i>Not Answered: <b>${s.unanswered}</b></span></div><div class="palette" aria-label="Question palette">${qs.map((x,i)=>`<button data-action="jump" data-index="${i}" class="${session.marked[x.id]?'review':session.answers[x.id]?'answered':'unanswered'} ${i===session.index?'current':''}" aria-label="Question ${i+1}, ${session.answers[x.id]?'answered':'unanswered'}${session.marked[x.id]?', marked for review':''}" ${i===session.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="small muted">Click a number to jump. Yellow takes priority for questions marked for review.</p><div class="palette-note"><strong>Learn as you go</strong><p>Read the explanation before moving on. Your answers are saved automatically.</p></div></aside></div>`;}
function updateTimer(){if(!session||session.submitted)return;const left=remaining(session.deadline);const el=document.querySelector('#timer');if(el){el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;el.classList.toggle('urgent',left<300);}if(left===0)finish(true);}
function finish(auto=false){if(!session||session.submitted)return;session.submitted=true;session.ended=Date.now();session.auto=auto;session.stats=score(sessionQuestions(),session.answers);result=structuredClone(session);history=[result,...history.filter(x=>x.id!==result.id)].slice(0,20);write('history',history);save();view='result';dialog=false;render();window.scrollTo(0,0);}
function confirmDialog(){const s=score(sessionQuestions(),session.answers);return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="submit-title"><h2 id="submit-title">Finish this practice?</h2><p>${s.attempted} answered · ${s.unanswered} unanswered. Unanswered questions receive 0 marks.</p><div>${button('Keep practicing','cancel','secondary')}${button('Submit & see results','finish','primary')}</div></section></div>`;}
function performanceTable(rows,topicTable=false,firstColumn='Subject'){return `<div class="table-scroll"><table><thead><tr><th>${topicTable?'Topic':firstColumn}</th><th>Attempted</th><th>Correct</th><th>Wrong</th><th>Accuracy</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}${topicTable&&r.wrong?'<span class="mistake-tag">Revisit</span>':''}</td><td>${r.attempted}/${r.total}</td><td class="good-text">${r.correct}</td><td class="bad-text">${r.wrong}</td><td>${r.attempted?r.accuracy.toFixed(0)+'%':'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function results(){if(!result)return '<p>No result available.</p>';const qs=result.ids.map(id=>allBank.find(q=>q.id===id)),s=score(qs,result.answers),topics=breakdown(qs,result.answers,'topic');return `<div class="page-title"><div><div class="eyebrow">PRACTICE COMPLETE</div><h1>Every session moves you forward.</h1><p>${esc(result.name)} · ${new Date(result.ended).toLocaleString()}${result.auto?' · Automatically submitted when time expired':''}</p></div>${button('Practice again','home','primary')}</div><div class="result-overview"><div class="score-card"><span>FINAL SCORE / MARKS OBTAINED</span><strong>${s.marks.toFixed(2)} <small>/ ${s.total}</small></strong><p>${s.correct} − (${s.wrong} × ⅓)</p></div><div class="result-stat"><b class="good-text">${s.correct}</b><span>Correct answers</span></div><div class="result-stat"><b class="bad-text">${s.wrong}</b><span>Wrong answers</span></div><div class="result-stat"><b>${s.unanswered}</b><span>Unanswered</span></div><div class="result-stat"><b>${s.accuracy.toFixed(1)}<small>%</small></b><span>Accuracy of attempts</span></div></div><div class="result-caption">Practice score reflects your final selections after feedback. ${button('Review all answers','review-result','secondary')}</div>${layerResults(qs,result.answers)}<section class="panel"><h2>Subject performance</h2>${performanceTable(breakdown(qs,result.answers,'subject'))}</section><section class="panel"><h2>Topic performance</h2><p class="muted">${topics.some(t=>t.wrong)?'Topics marked “Revisit” are where you made mistakes.':'No wrong answers recorded. Unattempted topics have no accuracy yet.'}</p>${performanceTable(topics,true)}</section>`;}
function layerResults(qs,answers){if(!qs.some(q=>layerOf(q)==='new'))return '';return `<section class="panel"><h2>Performance by question pool</h2>${performanceTable(['original','new'].map(layer=>({name:layer==='new'?NEW_LABEL:ORIGINAL_LABEL,...score(qs.filter(q=>layerOf(q)===layer),answers)})),false,'Question pool')}</section>`;}
function browse(){const qs=filtered(scopedBank()),pages=Math.max(1,Math.ceil(qs.length/10));bankPage=Math.min(bankPage,pages-1);return `<div class="page-title"><div><div class="eyebrow">STUDY & REVISE</div><h1>Question bank</h1><p>Original records and new practice are kept in separate pools. Answers are shown only when you open the explanation.</p></div></div><div class="filters"><label>Question pool<select data-field="bankLayer"><option value="original" ${bankLayer==='original'?'selected':''}>Original bank (432)</option><option value="new" ${bankLayer==='new'?'selected':''}>New practice (${newBank.length})</option><option value="mixed" ${bankLayer==='mixed'?'selected':''}>Both pools</option></select></label>${select('Subject','subject',subjects,subject,'All subjects')}${select('Topic','topic',topicsFor(scopedBank()),topic,'All topics')}${select('Difficulty','difficulty',[...new Set(bank.map(q=>q.difficulty))],difficulty,'All difficulties')}${button('Reset filters','reset-filters','secondary')}</div><div class="bank-label">${qs.length} questions <span>Page ${bankPage+1} of ${pages}</span></div>${qs.slice(bankPage*10,bankPage*10+10).map(q=>`<article class="bank-question panel"><div class="subject-line">${esc(q.subject)} / ${esc(q.topic)} <span class="badge">${esc(q.difficulty)}</span><span class="layer-label ${layerOf(q)}">${poolLabel(q)}</span><span class="source-tag">${esc(q.source_type)}</span></div>${q.status!=='ACTIVE'?'<div class="notice">Pending review · Answer-key conflict in source. Not used in scored practice. Answer below is preserved from the supplied bank.</div>':''}<h2>${text(q.question_text)}</h2><div class="bank-options">${letters.map(l=>`<p><b>${l}</b> ${text(q['option_'+l.toLowerCase()])}</p>`).join('')}</div><details><summary>View answer & explanation</summary>${explanation(q,null,true)}</details><details class="source-details"><summary>Source & metadata</summary><dl>${['id','subtopic','source_type','source_reference','verification_status','status','exam','exam_year','shift','generation_method','related_topics'].filter(k=>q[k]).map(k=>`<dt>${esc(k.replaceAll('_',' '))}</dt><dd>${text(q[k])}</dd>`).join('')}</dl></details></article>`).join('')||'<div class="panel">No questions match these filters.</div>'}<div class="pagination">${button('Previous page','bank-prev','secondary',bankPage===0?'disabled':'')}<span>${bankPage+1} / ${pages}</span>${button('Next page','bank-next','secondary',bankPage>=pages-1?'disabled':'')}</div>`;}
function historyView(){return `<div class="page-title"><div><div class="eyebrow">YOUR RECENT SESSIONS</div><h1>Practice results</h1><p>Your latest 20 results are saved in this browser.</p></div>${button('New practice','home','primary')}</div>${history.length?history.map((h,i)=>`<section class="recent"><div><h2>${esc(h.name)}</h2><p>${new Date(h.ended).toLocaleString()} · ${h.stats.attempted} answered</p></div><strong>${h.stats.marks.toFixed(2)} <small>/ ${h.stats.total}</small></strong>${button('View result','recent','secondary',`data-index="${i}"`)}</section>`).join(''):'<section class="panel empty"><h2>Your first session starts here.</h2><p>Complete a practice test to see your results.</p>'+button('Choose practice','home','primary')+'</section>'}`;}
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(['home','bank','history','mode','recent'].includes(action)&&reviewResult){session=activeBackup;activeBackup=null;reviewResult=false;}if(action==='theme'){theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;write('theme',theme);render();return;}if(['answer','clear','mark','next','previous','jump','submit'].includes(action)&&session&&!session.submitted&&remaining(session.deadline)===0){finish(true);return;}const q=sessionQuestions()[session?.index];switch(action){case 'home':view='home';break;case 'bank':view='bank';bankLayer='original';subject='';topic='';difficulty='';bankPage=0;break;case 'history':view='history';break;case 'mode':mode=b.dataset.mode;pool=mode==='new'?'new':mode==='mixed'?'mixed':mode==='auto'?'auto':'original';subject=mode==='subject'||mode==='topic'?subjects[0]:'';topic=mode==='topic'?available().find(q=>q.subject===subject)?.topic||'':'';difficulty='';count=20;view='setup';break;case 'start':start();return;case 'resume':reviewResult=false;view='practice';break;case 'answer':if(!reviewResult&&!session.submitted){session.answers[q.id]=b.dataset.letter;save();}break;case 'clear':if(!reviewResult){delete session.answers[q.id];save();}break;case 'mark':session.marked[q.id]=!session.marked[q.id];save();break;case 'next':session.index=Math.min(session.ids.length-1,session.index+1);save();break;case 'previous':session.index=Math.max(0,session.index-1);save();break;case 'jump':session.index=Number(b.dataset.index);save();break;case 'submit':dialog=true;break;case 'cancel':dialog=false;break;case 'finish':finish();return;case 'recent':result=history[Number(b.dataset.index)];view='result';break;case 'back-result':view='result';break;case 'review-result':activeBackup=session;session=structuredClone(result);reviewResult=true;session.index=0;view='practice';break;case 'reset-filters':subject='';topic='';difficulty='';bankPage=0;break;case 'bank-next':bankPage++;break;case 'bank-prev':bankPage--;break;}render();if(['next','previous','jump'].includes(action))document.querySelector('.question-text')?.focus({preventScroll:false});else if(!['answer','clear','mark','submit','cancel'].includes(action))window.scrollTo(0,0);if(dialog)document.querySelector('[data-action="cancel"]')?.focus();});
app.addEventListener('change',e=>{const k=e.target.dataset.field;if(k==='pool'){pool=e.target.value;topic=mode==='topic'?topicsFor(available())[0]||'':'';}if(k==='ratio')originalPercent=Number(e.target.value);if(k==='bankLayer'){bankLayer=e.target.value;subject='';topic='';difficulty='';}if(k==='subject'){subject=e.target.value;topic=mode==='topic'&&view==='setup'?available().find(q=>q.subject===subject)?.topic||'':'';}if(k==='topic')topic=e.target.value;if(k==='difficulty')difficulty=e.target.value;if(k==='count')count=Number(e.target.value);bankPage=0;render();});
document.addEventListener('keydown',e=>{if(!dialog)return;if(e.key==='Escape'){dialog=false;render();}if(e.key==='Tab'){const bs=[...document.querySelectorAll('.modal button')],i=bs.indexOf(document.activeElement);e.preventDefault();bs[(i+(e.shiftKey?-1:1)+bs.length)%bs.length]?.focus();}});
try{const r=await fetch('/questions.json');if(!r.ok)throw Error('Question bank unavailable');bank=await r.json();try{const extra=await fetch('/layer2.json');if(extra.ok)newBank=await extra.json();}catch{newBank=[];}allBank=[...bank,...newBank];eligible=bank.filter(q=>q.status==='ACTIVE'&&q.verification_status!=='KEY_CONFLICT');subjects=[...new Set(bank.map(q=>q.subject))].sort();if(session&&(!Array.isArray(session.ids)||session.ids.some(id=>!allBank.some(q=>q.id===id))))session=null;render();setInterval(updateTimer,1000);document.addEventListener('visibilitychange',updateTimer);}catch(err){app.innerHTML='<main><h1>Question bank could not load</h1><p>Please reload the page to try again.</p><button onclick="location.reload()">Reload</button></main>';console.error(err);}
